{
  "arguments": [
    {
      "claim": "The artillery attacks on Knin, Benkovac, Obrovac and Gračac constitute attacks on towns that were undefended and not military objectives, and are therefore unlawful under the Rome Statute.",
      "reasoning": "Article 8 of the Rome Statute expressly criminalises \"Attacking or bombarding, by whatever means, towns, villages, dwellings or buildings which are undefended and which are not military objectives\". The Trial Chamber’s forensic analysis showed that impact sites lay more than 200 metres from any verified military target, indicating that shells struck civilian areas. Moreover, the evidence demonstrates that the towns were not defended by armed forces at the time of the attacks. Consequently, the attacks fit the description of unlawful bombardment of undefended towns.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Attacking or bombarding, by whatever means, towns, villages, dwellings or buildings which are undefended and which are not military objectives"
        }
      ]
    },
    {
      "claim": "The artillery attacks caused extensive destruction that was not justified by military necessity, violating the prohibition on unnecessary destruction in the Rome Statute.",
      "reasoning": "Article 8 of the Rome Statute also prohibits \"Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly\". The large‑scale displacement of civilians from the Krajina region and the indiscriminate pattern of impacts demonstrate that the destruction far exceeded any concrete and direct military advantage. Expert testimony on wind and temperature effects further shows that the HV could not reliably limit the effects of its fire, indicating a lack of military necessity and a wanton approach to destruction.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly"
        }
      ]
    },
    {
      "claim": "The commanders failed to take feasible precautions to verify targets, rendering the artillery attacks indiscriminate and unlawful under the principle of distinction embodied in the Rome Statute.",
      "reasoning": "The principle of distinction, reflected in Article 8(b)(v) of the Rome Statute, requires parties to direct operations only against military objectives and to take all feasible precautions to avoid civilian harm. The Trial Chamber found that the HV could not identify targets of opportunity in the four towns and that a 200‑metre margin of error was applied uniformly, indicating a systemic inability to verify targets. This failure to adopt feasible verification measures makes the attacks indiscriminate, satisfying the statutory element of unlawful conduct.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Attacking or bombarding, by whatever means, towns, villages, dwellings or buildings which are undefended and which are not military objectives"
        }
      ]
    }
  ]
}

