{
  "arguments": [
    {
      "claim": "The artillery attacks on Knin, Benkovac, Obrovac and Gračac were indiscriminate attacks prohibited by article 8(2)(b)(iv) of the Rome Statute.",
      "reasoning": "The Trial Chamber found that the HV could not identify any legitimate military targets within the four towns and that impact sites were more than 200 metres from any verified target. Expert testimony established that wind speed and air temperature further degraded accuracy, making it foreseeable that shells would strike civilian areas. Consequently, the commanders launched attacks in the knowledge that the incidental loss of civilian life and damage to civilian objects would be clearly excessive in relation to the negligible concrete and direct military advantage anticipated, satisfying both the factual and mental elements of article 8(2)(b)(iv).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(b)(iv)",
          "quoted_text": "Intentionally launching an attack in the knowledge that such attack will cause incidental loss of life or injury to civilians or damage to civilian objects or widespread, long-term and severe damage to the natural environment which would be clearly excessive in relation to the concrete and direct overall military advantage anticipated"
        }
      ]
    },
    {
      "claim": "The commanders failed to take feasible precautions to verify targets, constituting a war crime under article 8(2)(b)(iv) of the Rome Statute.",
      "reasoning": "International humanitarian law obliges parties to take all feasible precautions to avoid civilian harm. The evidence shows that the HV applied a uniform 200‑metre margin of error and admitted an inability to identify targets of opportunity, despite awareness of environmental factors that reduced artillery accuracy. This demonstrates a failure to adopt feasible verification measures and to mitigate foreseeable civilian casualties. Launching the attacks under these circumstances indicates the commanders acted with knowledge that the attacks would cause excessive incidental civilian harm, fulfilling the mens rea requirement of article 8(2)(b)(iv).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(b)(iv)",
          "quoted_text": "Intentionally launching an attack in the knowledge that such attack will cause incidental loss of life or injury to civilians or damage to civilian objects or widespread, long-term and severe damage to the natural environment which would be clearly excessive in relation to the concrete and direct overall military advantage anticipated"
        }
      ]
    }
  ]
}

